additionalExercises.referenceSolution:
#include <algorithm>
#include <iostream>
#include <iterator>
#include <print>
#include <string>
#include <utility>
#include <vector>

std::string join(const std::vector<std::string> &items) {
    std::string s;
    for (const std::string &item : items) {
        s += (s.empty() ? "" : ", ") + item;
    }
    return s.empty() ? "—" : s;
}

int main() {
    std::vector<std::string> todo;
    std::vector<std::string> done;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            std::string text;
            std::cin >> text;
            todo.push_back(std::move(text));
        } else if (command == "finish") {
            std::size_t i;
            std::cin >> i;
            done.push_back(std::move(todo[i - 1]));
            todo.erase(todo.begin() + static_cast<std::ptrdiff_t>(i - 1));
        } else if (command == "finish-all") {
            std::ranges::move(todo, std::back_inserter(done));
            todo.clear();
        } else {
            std::println("дела: {}", join(todo));
            std::println("готово: {}", join(done));
        }
    }
    return 0;
}

